def check(candidate) -> bool:
    try:
        m = 11449
        T = 4
        if not isinstance(candidate, list):
            return False
        if len(candidate) == 0 or len(candidate) > 400:
            return False
        A = []
        for v in candidate:
            if isinstance(v, bool) or not isinstance(v, int):
                return False
            if v < 0 or v >= m:
                return False
            A.append(v)
        if len(set(A)) != len(A):
            return False
        k = len(A)
        # pigeonhole: k(k+1)/2 unordered pairs must fit in m residues with at most T each
        if k * (k + 1) // 2 > T * m:
            return False
        cnt = [0] * m
        for i in range(k):
            ai = A[i]
            for j in range(i, k):
                s = (ai + A[j]) % m
                cnt[s] += 1
                if cnt[s] > T:
                    return False
        for c in cnt:
            if c < 1:
                return False
        return True
    except Exception:
        return False
